"""Exact local public-function drift guard; no remote connection or auto-update."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / 'tests/fixtures/function-authority.json'


def verify_functions(actual):
    expected = json.loads(MANIFEST.read_text(encoding='utf-8'))['functions']

    def keyed(rows):
        if not isinstance(rows, list):
            raise RuntimeError('function inventory is not a list')
        result = {}
        for row in rows:
            if not isinstance(row, dict) or not isinstance(row.get('name'), str) or not isinstance(row.get('identity'), str):
                raise RuntimeError('function inventory identity is invalid')
            key = (row['name'], row['identity'])
            if key in result:
                raise RuntimeError('duplicate function identity')
            result[key] = row
        return result

    wanted, observed = keyed(expected), keyed(actual)
    if wanted.keys() != observed.keys():
        raise RuntimeError('unreviewed or missing public function identity')
    for key in wanted:
        if wanted[key] != observed[key]:
            raise RuntimeError('public function authority drift: ' + key[0])
    return len(wanted)

import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

/** Legacy intake is quarantined until authoritative sale commands are verified. */
export async function POST() {
  return NextResponse.json(
    { error: 'sync_unavailable', accepted: [] },
    { status: 503, headers: { 'Cache-Control': 'no-store' } }
  );
}

import type { z } from 'zod';

type RequestPolicyCode =
  | 'invalid_configuration'
  | 'method_not_allowed'
  | 'forbidden'
  | 'unsupported_media_type'
  | 'payload_too_large'
  | 'bad_request';

const STATUS_BY_CODE: Record<RequestPolicyCode, number> = {
  invalid_configuration: 503,
  method_not_allowed: 405,
  forbidden: 403,
  unsupported_media_type: 415,
  payload_too_large: 413,
  bad_request: 400
};

export class SessionRequestError extends Error {
  readonly code: RequestPolicyCode;
  readonly status: number;
  constructor(code: RequestPolicyCode, status: number) {
    super(code);
    this.name = 'SessionRequestError';
    this.code = code;
    this.status = status;
  }
}

function fail(code: RequestPolicyCode): never {
  throw new SessionRequestError(code, STATUS_BY_CODE[code]);
}

function isLoopbackHost(hostname: string): boolean {
  return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]';
}

function safeOrigin(value: string): string | null {
  try {
    return new URL(value).origin;
  } catch {
    return null;
  }
}

function validateTrustedOrigin(trustedOrigin: string): void {
  if (safeOrigin(trustedOrigin) !== trustedOrigin) fail('invalid_configuration');
  const url = new URL(trustedOrigin);
  if (url.protocol === 'https:') return;
  if (url.protocol === 'http:' && isLoopbackHost(url.hostname)) return;
  fail('invalid_configuration');
}

export function assertSameOriginMutation(request: Request, trustedOrigin: string): void {
  validateTrustedOrigin(trustedOrigin);
  if (request.method !== 'POST') fail('method_not_allowed');
  if (safeOrigin(request.url) !== trustedOrigin) fail('forbidden');
  if (request.headers.get('origin') !== trustedOrigin) fail('forbidden');
  if (request.headers.get('x-hc-request') !== '1') fail('forbidden');
  const secFetchSite = request.headers.get('sec-fetch-site');
  if (secFetchSite !== null && secFetchSite !== 'same-origin') fail('forbidden');
}

/** GET never refreshes or mutates a session; a same-origin header is still required. */
export function assertSameOriginRead(request: Request, trustedOrigin: string): void {
  validateTrustedOrigin(trustedOrigin);
  if (request.method !== 'GET') fail('method_not_allowed');
  if (safeOrigin(request.url) !== trustedOrigin) fail('forbidden');
  const origin = request.headers.get('origin');
  if (origin !== null && origin !== trustedOrigin) fail('forbidden');
  if (request.headers.get('x-hc-request') !== '1') fail('forbidden');
  const site = request.headers.get('sec-fetch-site');
  if (site !== null && site !== 'same-origin') fail('forbidden');
}

const CONTENT_TYPE_PATTERN = /^application\/json(?:\s*;\s*charset\s*=\s*utf-8)?\s*$/i;
const CONTENT_LENGTH_PATTERN = /^[0-9]+$/;

export async function readBoundedJson<T>(
  request: Request,
  schema: z.ZodType<T>,
  maxBytes = 4096,
  signal?: AbortSignal
): Promise<T> {
  if (!Number.isInteger(maxBytes) || maxBytes <= 0 || maxBytes > 65536)
    fail('invalid_configuration');
  const contentType = request.headers.get('content-type');
  if (contentType === null || !CONTENT_TYPE_PATTERN.test(contentType))
    fail('unsupported_media_type');
  const contentEncoding = request.headers.get('content-encoding');
  if (contentEncoding !== null && contentEncoding.trim().toLowerCase() !== 'identity') {
    fail('unsupported_media_type');
  }
  const contentLength = request.headers.get('content-length');
  if (contentLength !== null) {
    if (!CONTENT_LENGTH_PATTERN.test(contentLength)) fail('bad_request');
    const declared = Number(contentLength);
    if (!Number.isSafeInteger(declared)) fail('bad_request');
    if (declared > maxBytes) fail('payload_too_large');
  }
  if (request.body === null || request.bodyUsed) fail('bad_request');

  let reader: ReadableStreamDefaultReader<Uint8Array>;
  try { reader = request.body.getReader(); } catch { return fail('bad_request'); }
  const cancel = () => { void reader.cancel().catch(() => undefined); };
  signal?.addEventListener('abort', cancel, { once: true });
  if (signal?.aborted) cancel();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const result = await reader.read();
      if (result.done) break;
      total += result.value.byteLength;
      if (total > maxBytes) {
        void reader.cancel().catch(() => undefined);
        fail('payload_too_large');
      }
      chunks.push(result.value);
    }
  } catch (err) {
    if (err instanceof SessionRequestError) throw err;
    fail('bad_request');
  } finally {
    signal?.removeEventListener('abort', cancel);
    reader.releaseLock();
  }

  const combined = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    combined.set(chunk, offset);
    offset += chunk.byteLength;
  }

  let parsed: ReturnType<typeof schema.safeParse>;
  try {
    const text = new TextDecoder('utf-8', { fatal: true }).decode(combined);
    parsed = schema.safeParse(JSON.parse(text));
  } catch {
    fail('bad_request');
  }
  if (!parsed.success) fail('bad_request');
  return parsed.data;
}

/** expectedToken must come from the verified server session, never another request field. */
export function assertSessionCsrf(request: Request, expectedToken: string): void {
  const tokenShape = /^[A-Za-z0-9_-]{43}$/;
  if (!tokenShape.test(expectedToken)) fail('invalid_configuration');
  const supplied = request.headers.get('x-hc-csrf');
  if (supplied === null || !tokenShape.test(supplied)) fail('forbidden');
  let difference = 0;
  for (let i = 0; i < 43; i++) difference |= supplied.charCodeAt(i) ^ expectedToken.charCodeAt(i);
  if (difference !== 0) fail('forbidden');
}

import { z } from 'zod';
import {
  SessionRequestError,
  assertSameOriginMutation,
  assertSameOriginRead,
  assertSessionCsrf,
  readBoundedJson
} from './request-policy';

const COOKIE_NAME = '__Host-hc-session';
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;
const MAX_SESSION_SECONDS = 28800;
const DEADLINE_MS = 5000;
const MAX_COOKIE_HEADER_CHARS = 8192;

const SessionRecordSchema = z
  .object({
    sessionId: z.string().regex(TOKEN_PATTERN),
    csrfToken: z.string().regex(TOKEN_PATTERN),
    expiresAt: z.number().int(),
    profile: z
      .object({
        id: z.string().uuid(),
        role: z.enum(['owner', 'helper', 'support']),
        active: z.literal(true)
      })
      .strict()
  })
  .strict();

export type SessionRecord = z.infer<typeof SessionRecordSchema>;

type LimitAction = 'session' | 'login' | 'refresh' | 'logout';

export interface SessionAuthority {
  limit(request: Request, action: LimitAction, signal: AbortSignal): Promise<boolean>;
  login(
    credentials: { email: string; password: string },
    signal: AbortSignal
  ): Promise<SessionRecord | null>;
  read(sessionId: string, signal: AbortSignal): Promise<SessionRecord | null>;
  refresh(sessionId: string, signal: AbortSignal): Promise<SessionRecord | null>;
  logout(sessionId: string, signal: AbortSignal): Promise<void>;
}

type HandlerCode = 'unauthenticated' | 'not_found' | 'rate_limited' | 'dependency_unavailable';

class HandlerError extends Error {
  readonly code: HandlerCode;
  readonly status: number;
  constructor(code: HandlerCode, status: number) {
    super(code);
    this.name = 'HandlerError';
    this.code = code;
    this.status = status;
  }
}

const LoginBodySchema = z
  .object({ email: z.string().email().max(254), password: z.string().min(1).max(1024) })
  .strict();

const EmptyBodySchema = z.object({}).strict();

const BASE_HEADERS: Record<string, string> = {
  'Cache-Control': 'no-store',
  Pragma: 'no-cache',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer'
};

const ALLOW_BY_PATH: Record<string, string> = {
  '/api/v1/session': 'GET',
  '/api/v1/session/login': 'POST',
  '/api/v1/session/refresh': 'POST',
  '/api/v1/session/logout': 'POST'
};

function jsonResponse(
  status: number,
  body: unknown,
  extraHeaders?: Record<string, string>
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...BASE_HEADERS, 'Content-Type': 'application/json', ...(extraHeaders ?? {}) }
  });
}

function errorResponse(
  status: number,
  code: string,
  extraHeaders?: Record<string, string>
): Response {
  return jsonResponse(status, { code, correlationId: crypto.randomUUID() }, extraHeaders);
}

function cookieHeader(value: string | null, maxAgeSeconds: number): string {
  return `${COOKIE_NAME}=${value ?? ''}; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=${maxAgeSeconds}`;
}

function unauthorized(): Response {
  return errorResponse(401, 'unauthenticated', { 'Set-Cookie': cookieHeader(null, 0) });
}

/** Exact single-cookie parse: no decoding, duplicate/malformed/oversized rejected wholesale. */
function parseCookie(request: Request): string | null | 'invalid' {
  const header = request.headers.get('cookie');
  if (header === null) return null;
  if (header.length > MAX_COOKIE_HEADER_CHARS) return 'invalid';
  let found: string | null = null;
  for (const rawPart of header.split(';')) {
    const part = rawPart.trim();
    if (part.length === 0) continue;
    const eq = part.indexOf('=');
    if (eq === -1) {
      if (part === COOKIE_NAME) return 'invalid';
      continue;
    }
    if (part.slice(0, eq) !== COOKIE_NAME) continue;
    if (found !== null) return 'invalid';
    const value = part.slice(eq + 1);
    if (!TOKEN_PATTERN.test(value)) return 'invalid';
    found = value;
  }
  return found;
}

function checkRecord(
  raw: unknown,
  now: number,
  expectSessionId: string | null
): SessionRecord | 'expired' | 'malformed' {
  const parsed = SessionRecordSchema.safeParse(raw);
  if (!parsed.success) return 'malformed';
  const record = parsed.data;
  if (record.sessionId === record.csrfToken) return 'malformed';
  if (expectSessionId !== null && record.sessionId !== expectSessionId) return 'malformed';
  if (record.expiresAt > now + MAX_SESSION_SECONDS) return 'malformed';
  if (record.expiresAt <= now) return 'expired';
  return record;
}

function ensureActive(signal: AbortSignal): void {
  if (signal.aborted) throw new HandlerError('dependency_unavailable', 503);
}

/** Single deadline shared by every authority call made while handling one request. */
async function withDeadline<T>(fn: (signal: AbortSignal) => Promise<T>): Promise<T> {
  const controller = new AbortController();
  let timer!: ReturnType<typeof setTimeout>;
  const deadline = new Promise<never>((_, reject) => {
    timer = setTimeout(() => {
      reject(new HandlerError('dependency_unavailable', 503));
      controller.abort();
    }, DEADLINE_MS);
  });
  try {
    return await Promise.race([fn(controller.signal), deadline]);
  } finally {
    clearTimeout(timer);
  }
}

async function loadSession(
  request: Request,
  authority: SessionAuthority,
  now: () => number,
  signal: AbortSignal
): Promise<SessionRecord | 'unauthorized' | 'malformed'> {
  const cookieValue = parseCookie(request);
  if (cookieValue === null || cookieValue === 'invalid') return 'unauthorized';
  ensureActive(signal);
  const raw = await authority.read(cookieValue, signal);
  ensureActive(signal);
  if (raw === null) return 'unauthorized';
  const checked = checkRecord(raw, now(), cookieValue);
  if (checked === 'malformed') return 'malformed';
  if (checked === 'expired') return 'unauthorized';
  return checked;
}

function successResponse(record: SessionRecord, cookieValue?: string, maxAge?: number): Response {
  const headers: Record<string, string> =
    cookieValue !== undefined && maxAge !== undefined
      ? { 'Set-Cookie': cookieHeader(cookieValue, maxAge) }
      : {};
  return jsonResponse(
    200,
    {
      profile: { id: record.profile.id, role: record.profile.role },
      csrfToken: record.csrfToken,
      expiresAt: record.expiresAt
    },
    headers
  );
}

async function handleRead(
  request: Request,
  origin: string,
  authority: SessionAuthority,
  now: () => number
): Promise<Response> {
  assertSameOriginRead(request, origin);
  return withDeadline(async (signal) => {
    if (!(await authority.limit(request, 'session', signal)))
      throw new HandlerError('rate_limited', 429);
    ensureActive(signal);
    const session = await loadSession(request, authority, now, signal);
    if (session === 'malformed') throw new HandlerError('dependency_unavailable', 503);
    if (session === 'unauthorized') return unauthorized();
    return successResponse(session);
  });
}

async function handleLogin(
  request: Request,
  origin: string,
  authority: SessionAuthority,
  now: () => number
): Promise<Response> {
  assertSameOriginMutation(request, origin);
  return withDeadline(async (signal) => {
    if (!(await authority.limit(request, 'login', signal)))
      throw new HandlerError('rate_limited', 429);
    ensureActive(signal);
    const credentials = await readBoundedJson(request, LoginBodySchema, 4096, signal);
    ensureActive(signal);
    const raw = await authority.login(credentials, signal);
    ensureActive(signal);
    if (raw === null) return unauthorized();
    const stamp = now();
    const checked = checkRecord(raw, stamp, null);
    if (checked === 'malformed' || checked === 'expired')
      throw new HandlerError('dependency_unavailable', 503);
    return successResponse(checked, checked.sessionId, checked.expiresAt - stamp);
  });
}

async function handleRefresh(
  request: Request,
  origin: string,
  authority: SessionAuthority,
  now: () => number
): Promise<Response> {
  assertSameOriginMutation(request, origin);
  return withDeadline(async (signal) => {
    if (!(await authority.limit(request, 'refresh', signal)))
      throw new HandlerError('rate_limited', 429);
    ensureActive(signal);
    await readBoundedJson(request, EmptyBodySchema, 64, signal);
    const session = await loadSession(request, authority, now, signal);
    if (session === 'malformed') throw new HandlerError('dependency_unavailable', 503);
    if (session === 'unauthorized') return unauthorized();
    assertSessionCsrf(request, session.csrfToken);
    ensureActive(signal);
    const raw = await authority.refresh(session.sessionId, signal);
    ensureActive(signal);
    if (raw === null) return unauthorized();
    const stamp = now();
    const checked = checkRecord(raw, stamp, null);
    if (checked === 'malformed' || checked === 'expired')
      throw new HandlerError('dependency_unavailable', 503);
    if (checked.profile.id !== session.profile.id)
      throw new HandlerError('dependency_unavailable', 503);
    return successResponse(checked, checked.sessionId, checked.expiresAt - stamp);
  });
}

async function handleLogout(
  request: Request,
  origin: string,
  authority: SessionAuthority,
  now: () => number
): Promise<Response> {
  assertSameOriginMutation(request, origin);
  return withDeadline(async (signal) => {
    if (!(await authority.limit(request, 'logout', signal)))
      throw new HandlerError('rate_limited', 429);
    ensureActive(signal);
    await readBoundedJson(request, EmptyBodySchema, 64, signal);
    const session = await loadSession(request, authority, now, signal);
    if (session === 'malformed') throw new HandlerError('dependency_unavailable', 503);
    if (session === 'unauthorized') return unauthorized();
    assertSessionCsrf(request, session.csrfToken);
    ensureActive(signal);
    await authority.logout(session.sessionId, signal);
    return new Response(null, {
      status: 204,
      headers: { ...BASE_HEADERS, 'Set-Cookie': cookieHeader(null, 0) }
    });
  });
}

export async function handleSessionRequest(
  request: Request,
  options: { origin: string; authority: SessionAuthority; now?: () => number }
): Promise<Response> {
  const { origin, authority } = options;
  const clock = options.now ?? (() => Math.floor(Date.now() / 1000));
  const now = () => {
    const value = clock();
    if (!Number.isSafeInteger(value) || value < 0) throw new HandlerError('dependency_unavailable', 503);
    return value;
  };

  let path: string;
  try {
    path = new URL(request.url).pathname;
  } catch {
    return errorResponse(503, 'dependency_unavailable');
  }
  const allow = ALLOW_BY_PATH[path];
  if (allow === undefined) return errorResponse(404, 'not_found');

  try {
    switch (path) {
      case '/api/v1/session':
        return await handleRead(request, origin, authority, now);
      case '/api/v1/session/login':
        return await handleLogin(request, origin, authority, now);
      case '/api/v1/session/refresh':
        return await handleRefresh(request, origin, authority, now);
      default:
        return await handleLogout(request, origin, authority, now);
    }
  } catch (err) {
    if (err instanceof SessionRequestError) {
      return errorResponse(err.status, err.code, err.status === 405 ? { Allow: allow } : undefined);
    }
    if (err instanceof HandlerError) {
      return errorResponse(err.status, err.code, err.status === 429 ? { 'Retry-After': '60' } : undefined);
    }
    return errorResponse(503, 'dependency_unavailable');
  }
}

import { NextResponse, type NextRequest } from 'next/server';
import { createServerClient } from '@supabase/ssr';
import { hasSupabaseConfig } from '@/lib/supabase/config';

/**
 * Refreshes the Supabase session on every request so a phone left open overnight is
 * still signed in, and keeps the staff screens off the public internet.
 *
 * The four customer screens are deliberately open: a customer ordering cookies does not
 * get an account.
 */
const PUBLIC_PATHS = ['/shop', '/checkout', '/status', '/lookup'];

export async function middleware(request: NextRequest) {
  let response = NextResponse.next({ request });

  // The quarantined endpoint returns only 503/no ACK and must never contact auth.
  if (request.nextUrl.pathname === '/api/sync') return response;

  /**
   * No backend configured — run the app anyway, unauthenticated.
   *
   * This branch is what makes the very first deploy work. Without it,
   * `createServerClient(undefined!, undefined!)` throws, and because this middleware's
   * matcher covers every route, EVERY page returns 500 — including the 24 screens that
   * need no database at all. You would push to Vercel, get a wall of server errors, and
   * have no way to tell a configuration mistake from a broken build.
   *
   * The books live in localStorage at this stage (docs/TECH-DEBT.md item 1), so the app
   * is genuinely usable like this. Sign-in and the sync endpoint are the only things that
   * need Supabase, and both fail with a message that names the missing variable.
   *
   * Remove this branch only once Supabase is required for the app to function at all —
   * which is after T-14, not before.
   */
  if (!hasSupabaseConfig()) return response;

  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL as string,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY as string,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll: (list) => {
          list.forEach(({ name, value }) => request.cookies.set(name, value));
          response = NextResponse.next({ request });
          list.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
        }
      }
    }
  );

  const { data } = await supabase.auth.getUser();
  const path = request.nextUrl.pathname;
  const isPublic = PUBLIC_PATHS.some((p) => path === p || path.startsWith(p + '/'));

  if (!data.user && !isPublic && path !== '/sign-in') {
    const url = request.nextUrl.clone();
    url.pathname = '/sign-in';
    url.searchParams.set('next', path);
    return NextResponse.redirect(url);
  }

  return response;
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|assets|sw.js|manifest.webmanifest|favicon.ico).*)']
};

-- The Happy Cookie Ops — initial schema.
--
-- Shape follows docs/reference/spec/02-data-model.md, which was derived from the
-- prototype's single localStorage object. Money is stored in centavos as bigint:
-- the prototype's peso values are all two-decimal, and float arithmetic on a
-- bookkeeping ledger is not acceptable.
--
-- Every table is owned by exactly one bakery (single tenant today, but the column
-- is here so a second one never needs a migration under load).

create extension if not exists "pgcrypto";

-- ---------------------------------------------------------------- identity

create type app_role as enum ('owner', 'helper', 'support');

create table profiles (
  id          uuid primary key references auth.users on delete cascade,
  role        app_role not null default 'helper',
  display_name text not null,
  created_at  timestamptz not null default now()
);

comment on table profiles is
  'One row per signed-in staff member. Customers are not users — they order by name and phone.';

-- role lookup used by every policy below. security definer so the policy can read
-- profiles without recursing into profiles'' own policy.
create or replace function current_role_name() returns app_role
language sql stable security definer set search_path = public as $$
  select role from profiles where id = auth.uid()
$$;

create or replace function is_owner() returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(current_role_name() = 'owner', false)
$$;

create or replace function is_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select current_role_name() is not null
$$;

-- ---------------------------------------------------------------- catalogue

create table products (
  id          text primary key,               -- 'dcf', 'hc', … the prototype's ids
  name        text not null,
  short_name  text not null,
  price_cents bigint not null check (price_cents >= 0),
  kind        text not null,
  tag         text not null default '',
  description text not null default '',
  image_path  text not null default '',
  active      boolean not null default true,
  sort_order  int not null default 0
);

create table recipes (
  product_id  text primary key references products on delete cascade,
  yield_count int not null check (yield_count > 0)
);

create table recipe_ingredients (
  id          uuid primary key default gen_random_uuid(),
  product_id  text not null references recipes on delete cascade,
  item_name   text not null,
  qty         numeric(12, 3) not null,
  unit        text not null
);

create table suppliers (
  id         text primary key,
  name       text not null,
  phone      text not null default '',
  notes      text not null default ''
);

create table inventory_items (
  id            text primary key,
  name          text not null,
  unit          text not null,
  on_hand       numeric(12, 3) not null default 0,
  par_level     numeric(12, 3) not null default 0,
  pack_size     numeric(12, 3),
  supplier_id   text references suppliers on delete set null,
  use_by_days   int,
  last_counted  timestamptz
);

-- ---------------------------------------------------------------- ordering

-- The engine's own status strings, verbatim, including the spaces and the capitals.
--
-- This looks unusual and is deliberate. The alternative is snake_case values plus a
-- mapping layer, and a mapping layer between the engine's status and the database's state
-- is exactly the two-places-for-one-truth bug that src/lib/rules/capacity.ts exists to
-- prevent. This is a 1:1 port; the engine's vocabulary is the vocabulary.
--
-- Every value here is read out of ops-engine.js (STATUS_LABEL, RECOGNISED, PLANNED).
-- 'Payment review' is where an order starts, awaiting proof of payment.
-- 'No-show'        nobody collected. They stay paid AND the cookies go back into stock —
--                  a real rule with money on both sides, and the previous version of this
--                  enum could not represent it at all.
create type order_state as enum (
  'Payment review', 'Confirmed', 'Preparing', 'Ready', 'Completed', 'Cancelled', 'No-show'
);

create type pay_state as enum ('unpaid', 'claimed', 'confirmed', 'refunded');

-- Revenue recognition, from the engine's RECOGNISED list. A no-show counts: she keeps the
-- money. Expressed as a function so the P&L query and the closeout cannot disagree.
create or replace function state_is_recognised(p_state order_state)
returns boolean
language sql
immutable
as $$
  select p_state in ('Confirmed', 'Preparing', 'Ready', 'Completed', 'No-show');
$$;

-- The engine's RESERVING list: states that hold capacity against a drop.
create or replace function state_reserves_capacity(p_state order_state)
returns boolean
language sql
immutable
as $$
